"""Self-contained Chinese review document with exact NBT images and feedback."""
from pathlib import Path
import base64,csv,html,json,shutil
CASE=Path(__file__).resolve().parents[1]
RUN=CASE/'runs/V1_r02';OUT=CASE/'deliverables';OUT.mkdir(exist_ok=True)
PICS=CASE/'review/previews/V1_r02'

def data(p):return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
def esc(s):return html.escape(str(s),quote=True)

def main():
    m=json.loads((RUN/'manifest.json').read_text());im=json.loads((RUN/'import_pack/import_manifest.json').read_text())
    refs=json.loads((CASE/'research/image_sources.json').read_text());accepted=[r for r in refs if r['selected']]
    views=[('overview','整体日景','塔、露台与山体整体关系'),('night','整体夜景','同机位；暖色步道与冷暖室内灯'),('site_top','场地俯视','北在上；道路、平台、建筑与林地'),('podium','多层基座','退后的玻璃、外廊、柱列和外楼梯'),('podium_night','基座夜景','固定外部灯与内部灯分开处理'),('observation_pod','观景舱近景','宽下舱、窄上舱、内收底部与放射肋'),('antenna','天线近景','开放框架、红白节段与局部装饰灯'),('park_north','公园北侧','上站、烽燧台、八角亭与塔的关系'),('pavilion','八角亭','石台、红柱与灰瓦檐的简化表达'),('north_elevation','北侧立面','观察塔高、天线与山体的竖向比例')]
    assets={k:{'title':t,'caption':c,'src':data(PICS/(k+'.png'))} for k,t,c in views}
    assets['terrain_evidence']={'title':'地形证据','caption':'左：实际取得的高程采样；右：插值坡势和局部台地解释。','src':data(CASE/'review/terrain_evidence.png')}
    def fig(k,extra=''):
        a=assets[k];return f'<figure class="{extra}"><button class="picture" data-view="{k}" aria-label="放大{esc(a["title"])}"><img data-image="{k}" alt="{esc(a["title"])}" loading="lazy"></button><figcaption><b>{esc(a["title"])}</b><span>{esc(a["caption"])}</span><em>点击查看大图</em></figcaption></figure>'
    source_rows=''.join(f'<tr><td><a href="{esc(r["url"])}" target="_blank" rel="noopener">{esc(r["id"])}</a></td><td>{esc(r["observation"])}</td><td>{"官方" if r["source_confidence"]=="official" else "摄影者实拍"}</td></tr>' for r in accepted)
    materials=list(csv.DictReader((RUN/'materials.csv').open(encoding='utf-8-sig')))
    materials.sort(key=lambda q:int(q['count']),reverse=True)
    material_rows=''.join(f'<tr><td>{esc(r["block_id"].removeprefix("minecraft:"))}</td><td>{int(r["count"]):,}</td><td>{r["stacks"]} 组 + {r["remainder"]}</td></tr>' for r in materials)
    cards=''.join(f'<button class="viewcard" data-view="{k}"><img data-image="{k}" loading="lazy" alt="{esc(t)}"><b>{esc(t)}</b><span>{esc(c)}</span></button>' for k,t,c in views)
    content=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>南山首尔塔 V1 · HAF 0.2</title>
<style>
:root{{--ink:#1e3028;--muted:#627168;--paper:#f4f2e9;--line:#d2d8ca;--green:#244f3c;--accent:#bd8755;--white:#fffef8}}*{{box-sizing:border-box}}html{{scroll-behavior:smooth}}body{{margin:0;background:var(--paper);color:var(--ink);font:16px/1.75 system-ui,-apple-system,"Noto Sans CJK SC","Microsoft Yahei",sans-serif}}a{{color:var(--green);text-underline-offset:4px}}header,main,footer{{max-width:1280px;margin:auto;padding:40px 40px 24px}}header{{padding-top:48px}}.eyebrow{{font-size:12px;letter-spacing:.2em;color:var(--muted)}}h1{{font-size:clamp(32px,5vw,62px);line-height:1.15;font-weight:650;letter-spacing:-.035em;margin:18px 0}}h1 small{{display:block;font-size:20px;letter-spacing:.1em;font-weight:400;margin-top:18px;color:var(--muted)}}.intro{{max-width:820px;font-size:18px;color:#4c6155}}.pill{{display:inline-block;border:1px solid var(--line);border-radius:30px;padding:4px 13px;font-size:12px;margin:0 7px 8px 0}}nav{{position:sticky;top:0;z-index:5;background:#f4f2e9f2;border-block:1px solid var(--line);backdrop-filter:blur(12px);overflow:auto}}nav div{{max-width:1280px;margin:auto;display:flex;gap:24px;padding:12px 40px;white-space:nowrap}}nav a{{font-size:13px;text-decoration:none}}section{{padding:40px 0;border-bottom:1px solid var(--line);scroll-margin-top:54px}}.sectionhead{{display:flex;gap:20px;align-items:baseline;margin-bottom:20px}}.sectionhead span{{color:var(--accent);font-size:13px;font-weight:700}}h2{{margin:0;font-size:29px;font-weight:600}}h3{{font-size:20px;font-weight:600;margin:22px 0 8px}}p{{margin:10px 0 20px}}.stats{{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--line);margin:24px 0}}.stat{{padding:22px;border-right:1px solid var(--line)}}.stat:last-child{{border:0}}.stat strong{{font:36px/1.1 Georgia,serif;display:block;margin-bottom:10px}}.stat span{{font-size:13px;color:var(--muted)}}.hero{{margin:0;background:#d6e0dc;border-radius:12px;overflow:hidden}}.hero img{{width:100%;display:block}}.toolbar{{display:flex;align-items:center;gap:10px;margin:16px 0;flex-wrap:wrap}}button,.button{{font:inherit;cursor:pointer;border:1px solid var(--line);border-radius:7px;background:var(--white);padding:9px 16px;color:var(--ink)}}button:hover,.button:hover{{border-color:var(--green)}}button.active,.primary{{background:var(--green);color:white}}.small{{font-size:13px;color:var(--muted)}}.twocol{{display:grid;grid-template-columns:1fr 1fr;gap:24px;align-items:start}}figure{{margin:0;background:#e5e9e0;border-radius:9px;overflow:hidden}}.picture{{padding:0;border:0;border-radius:0;width:100%;display:block;background:transparent}}.picture img{{display:block;width:100%;height:auto}}figcaption{{padding:15px 18px;background:var(--white);font-size:13px}}figcaption b{{display:block;font-size:15px}}figcaption span{{display:block;color:var(--muted)}}figcaption em{{font-style:normal;color:var(--accent);display:block;margin-top:6px}}.gallery{{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}}.viewcard{{padding:0;overflow:hidden;text-align:left;background:var(--white)}}.viewcard img{{width:100%;height:210px;object-fit:contain;background:#d7e1dd;display:block}}.viewcard b,.viewcard span{{display:block;margin:10px 15px}}.viewcard span{{font-size:12px;color:var(--muted)}}.note{{border-left:3px solid var(--accent);padding:15px 20px;background:#ebe8dc;font-size:14px}}table{{width:100%;border-collapse:collapse;font-size:14px;table-layout:auto}}th,td{{text-align:left;vertical-align:top;padding:13px 12px;border-bottom:1px solid var(--line)}}th{{background:#e5e9df;font-weight:600}}td:first-child{{word-break:break-word}}.tablewrap{{overflow:auto}}details{{margin:18px 0}}summary{{cursor:pointer;color:var(--green);font-weight:600}}code,pre{{font-family:ui-monospace,monospace;font-size:12px}}pre{{white-space:pre-wrap;background:#e7e9e1;padding:18px;border-radius:6px;word-break:break-all}}.feedback{{background:var(--white);border:1px solid var(--line);padding:24px;border-radius:9px}}label{{display:block;font-size:14px;margin:12px 0 6px}}select,textarea,input{{font:inherit;width:100%;padding:10px;border:1px solid var(--line);border-radius:5px;background:#fff}}textarea{{min-height:110px;resize:vertical}}footer{{font-size:12px;color:var(--muted);padding-bottom:50px}}.modal{{position:fixed;inset:0;z-index:20;background:#102018f7;display:none;overflow:auto;color:white}}.modal.open{{display:block}}.modalbar{{position:sticky;top:0;z-index:21;background:#142a21;padding:12px 22px;display:flex;gap:14px;align-items:center;flex-wrap:wrap}}.modalbar b{{margin-right:auto}}.modalbody{{padding:25px;text-align:center}}.modalbody img{{max-width:96%;max-height:83vh;width:auto;height:auto;display:inline-block}}.modalbody.actual img{{max-width:none;max-height:none}}.modalbar a{{color:white}}.muted{{color:var(--muted)}}.badge{{font-size:12px;border:1px solid #a6baa7;padding:3px 8px;border-radius:12px;white-space:nowrap}}@media(max-width:760px){{header,main,footer{{padding-inline:20px}}nav div{{padding-inline:20px;gap:18px}}.twocol,.gallery{{grid-template-columns:1fr}}.stats{{grid-template-columns:1fr 1fr}}.stat:nth-child(2){{border-right:0}}h2{{font-size:24px}}.viewcard img{{height:280px}}td,th{{padding:10px 8px;font-size:12px}}.modalbody{{padding:8px}}}}
</style></head><body>
<header><div class="eyebrow">HAF 0.2 · REAL BUILDING STUDY / 01</div><h1>南山首尔塔<small>N SEOUL TOWER — 山顶公园与多层露台</small></h1><p class="intro">把塔放回它所在的山顶。沿用 HAF 的方块表达和回读流程，将塔体、观景舱、天线、基座与公园作为相互连接的构件处理。</p><div><span class="pill">V1 · 交付基线 r02</span><span class="pill">2026-10-23</span><span class="pill">图片＋文字＋地图＋地形</span><span class="pill">未使用 SU 模型</span></div>
<div class="stats"><div class="stat"><strong>237</strong><span>塔体高度 / 格 · 约1格/米</span></div><div class="stat"><strong>320²</strong><span>山顶场地 / 平方格</span></div><div class="stat"><strong>709,460</strong><span>非空气方块 / 含山体壳与树林</span></div><div class="stat"><strong>10</strong><span>实际NBT回读视图 / 可放大</span></div></div></header>
<nav><div>{''.join(f'<a href="#s{i}">{i:02d} {t}</a>' for i,t in enumerate(['成果','公园','塔体','基座','夜景','地形','证据','材料','验收','反馈'],1))}</div></nav>
<main><section id="s1"><div class="sectionhead"><span>01</span><h2>先看完整的空间关系</h2></div><div class="toolbar"><button id="day" class="active">日景</button><button id="night">夜景</button><button id="herozoom">查看大图</button><span class="small">同一机位、同一建筑文件</span></div><figure class="hero"><img id="hero" alt="南山塔与山顶公园全景"></figure><p class="small">这些图由导出的 NBT 独立读回后渲染，没有使用生成式图片补景。方块纹理、透明度和光照为离线近似，尚不是 Minecraft 游戏截图。场地地图数据：© OpenStreetMap contributors，ODbL。</p><div class="gallery">{cards}</div></section>
<section id="s2"><div class="sectionhead"><span>02</span><h2>公园并入建筑，而非另铺一块平地</h2></div><p>这版覆盖山顶约320×320米：上层广场、八角亭、烽燧台、缆车上站附近步道、次级通信塔与林地。平面位置依据地图，步道顺坡；商业露台在南侧下降，北侧连接更高的平台。</p><div class="twocol">{fig('site_top')}{fig('park_north')}</div><p class="note">范围是山顶局部，并未制作整个南山公园。645棵树的分布、大小和树种是程序化近似；上站建筑也仅有地图体块与简化立面。</p>{fig('pavilion')}</section>
<section id="s3"><div class="sectionhead"><span>03</span><h2>塔身、观景舱和天线各自成形</h2></div><div class="twocol">{fig('observation_pod')}{fig('antenna')}</div><div class="tablewrap"><table><thead><tr><th>构件</th><th>这版采用的表达</th><th>需要继续看什么</th></tr></thead><tbody><tr><td>核心筒</td><td>细长白色空心筒，内部服务楼板止于内壁</td><td>照片比例下的直径与轻微收分</td></tr><tr><td>设备环</td><td>外缘、辐条、栏杆与少量设备；中间保留透空</td><td>设备数量及两个环的准确高度</td></tr><tr><td>观景舱</td><td>宽下舱、窄上舱、玻璃与水平层带；底面向内收拢并设放射肋</td><td>幕墙分格密度、楼层带厚度与真实舱高</td></tr><tr><td>天线</td><td>红白节段、逐段收细的四腿框架、横撑、斜撑与设备平台</td><td>1米网格下红色立柱略粗，顶部细杆与现实设备尚有简化</td></tr></tbody></table></div></section>
<section id="s4"><div class="sectionhead"><span>04</span><h2>基座的层次在近景里检查</h2></div>{fig('podium')}<p>横向露台板在前，玻璃围护退后，棕色竖向构件与吊顶网格形成另一层。外楼梯、玻璃电梯井、屋顶圆形游客空间分别处理；房间内有楼板、柱、桌面、书架和局部绿植。</p><p class="note">真实商业室内没有逐间测绘，这些家具属于可见深度与用途的近似表达。电梯和缆车没有运行机关。八角亭的石台、红柱与灰瓦檐也仍是简化样式，尚不能据此认定传统建筑细节已成熟。</p></section>
<section id="s5"><div class="sectionhead"><span>05</span><h2>灯光分成固定外部灯与内部活动灯</h2></div>{fig('podium_night')}<p>最终文件中有189块荧石、147块海晶灯和2支红石火把。步道以暖色点光为主，商业露台按层使用冷暖灯，室内使用固定种子与稳定位置生成变化。主天线带局部红玻璃装饰灯罩及顶端灯点。</p><p class="note">真实南山塔有大范围彩色投光。当前原版方块光照和离线预览没有重现蓝色RGB泛光；白色塔身夜间偏暗是明确保留的缺口。红玻璃灯罩也不会使原版照明变成真实红色光束，且没有模拟闪烁。</p></section>
<section id="s6"><div class="sectionhead"><span>06</span><h2>附近地形确实读取了，精度也明确保留</h2></div>{fig('terrain_evidence')}<p>从 OpenTopoData 读取 SRTM 约30米精度数据，保存121个采样点；取得的高程范围为180–270米。将坡势插值到方块网格后，再按地图与官方场地照片校正局部平台。</p><div class="tablewrap"><table><thead><tr><th>来源</th><th>用在哪一部分</th><th>本轮没有直接采用的部分</th></tr></thead><tbody><tr><td>SRTM / OpenTopoData</td><td>周围山势、坡向与相对高差</td><td>把30米采样当成台阶、屋顶或挡墙的细测量</td></tr><tr><td>OpenStreetMap</td><td>道路、广场、塔下轮廓、亭与上站的位置</td><td>与官方总高冲突的塔体分层标签</td></tr><tr><td>官方楼层图与照片</td><td>高低平台、外楼梯、围护和露台叠置</td><td>从示意图伪造厘米级精确尺寸</td></tr></tbody></table></div><p class="small">旧官方页面出现270米、2026官方手册出现243米的山高标注；塔旁SRTM值还会受屋顶/树冠影响。本轮没有取平均：塔基采用243米设计锚点，公园坡势保留SRTM，再对台地单独解释。共同测量基准尚待核实。</p></section>
<section id="s7"><div class="sectionhead"><span>07</span><h2>参考来源与构件判断留下记录</h2></div><p>采用13张照片或示意图及1份官方手册，另有1张宣传拼贴被排除。研究不设六图上限；是否增加图片取决于构件缺口，而不是凑数量。原图库图片仅保留链接与分析记录，下面可直接回看来源。</p><div class="tablewrap"><table><thead><tr><th>素材</th><th>观察与用途</th><th>来源</th></tr></thead><tbody>{source_rows}</tbody></table></div><p class="small">补充：<a href="https://www.nseoultower.co.kr/eng/global/intro2.asp" target="_blank">塔方尺寸资料</a> · <a href="https://www.nseoultower.co.kr/eng/visit/floor.asp" target="_blank">塔方楼层目录</a> · <a href="https://www.opentopodata.org/datasets/srtm/" target="_blank">SRTM来源说明</a> · <a href="https://www.openstreetmap.org/copyright" target="_blank">地图许可与贡献者</a></p></section>
<section id="s8"><div class="sectionhead"><span>08</span><h2>建筑文件与材料</h2></div><div class="tablewrap"><table><thead><tr><th>文件</th><th>用途与状态</th></tr></thead><tbody><tr><td>Namsan_Tower_HAF_V1.schem</td><td>Sponge v3，{im['schematic']['bytes']:,}字节；非空气方块与NBT一致。完整单文件，包含空气。</td></tr><tr><td>Namsan_Tower_HAF_V1.nbt</td><td>Java结构NBT，{m['bytes']:,}字节；稀疏导出，不包含显式空气。</td></tr><tr><td>modules / 14个NBT</td><td>全部≤256KiB；最大{im['module_max_bytes']:,}字节；带统一原点的偏移表，重组逐格一致。</td></tr><tr><td>materials.csv</td><td>41种方块ID、100种状态；统计包含山体壳、森林、道路与建筑。</td></tr></tbody></table></div><p>完整包围盒为 <b>320×308×320 格</b>。原点是西北侧底角，X向东、-Z向北；若原点放在Y=0，塔基位于Y=67，塔尖位于Y=303。NBT包内有导入说明，实际游戏/模组配置仍需验证。</p><p class="small">材料数按输出方块统计；半砖按放置的半砖方块记录。地形内部留空，不是实心地质模型。建筑包与源码包请从本次聊天附件下载。</p><details><summary>展开全部材料清单</summary><div class="tablewrap"><table><thead><tr><th>方块ID</th><th>数量</th><th>按64个/组</th></tr></thead><tbody>{material_rows}</tbody></table></div></details><p class="small">WorldEdit操作参考：<a href="https://worldedit.enginehub.org/en/latest/usage/clipboard/" target="_blank">官方剪贴板与schem说明</a>；本轮没有连接或修改游戏世界。</p></section>
<section id="s9"><div class="sectionhead"><span>09</span><h2>已经验证到哪一步</h2></div><div class="twocol"><div><h3>通过的离线检查</h3><ul><li>HAF核心26项测试；本案例22项检查。</li><li>同种子重建得到完全相同的NBT哈希。</li><li>NBT回读、Sponge转换和14分块重组一致。</li><li>10张预览都记录了同一源NBT哈希。</li><li>原BuildKit与历史建筑基线未改写。</li></ul></div><div><h3>留给下一轮的验收</h3><ul><li>Minecraft实际导入与光照效果。</li><li>步道、台阶、入口的完整通行检查。</li><li>亭檐、天线杆件和真实幕墙分格的精修。</li><li>平台高差的更细地图/实测校正。</li><li>塔身彩色泛光的可接受方块化方案。</li></ul></div></div><details><summary>本轮修正记录与文件指纹</summary><p>r01内部服务楼板越过白色外墙，造成假的灰色条纹；r02将楼板收回内侧。公园平台上的不适当木质条带已移除，部分坡地铺装改为楼梯。首个八角亭相机发生前景遮挡与近裁切，已更换机位，建筑文件未因此改变。</p><pre>交付 run: V1_r02\n重复 run: V1_replay\nNBT SHA-256: {m['sha256']}\n几何 SHA-256: {m['geometry_sha256']}\n源码快照、参数、组件归属、地形响应与检查报告均随工程保存。</pre></details><p>本轮沿用 HAF 0.2，新增南山案例与独立场地预算支持；经验写入工程学习记录。没有新增独立Skill，也不把这个案例称为任意建筑自动重建能力。下一轮沙面类建筑应重新研究柱廊、窗楣、檐口、坡屋顶和街巷尺度。</p></section>
<section id="s10"><div class="sectionhead"><span>10</span><h2>把品鉴意见留给下一版</h2></div><p>按构件记录“哪里不对、从哪个角度看到、哪些特征要保留”。保存按钮只在本地生成反馈JSON，不会上传或改动工程。</p><div class="feedback"><div class="twocol"><div><label for="component">构件</label><select id="component"><option value="tower.shaft">白色塔身</option><option value="tower.pod">观景舱 / 幕墙 / 底肋</option><option value="tower.antenna">主天线</option><option value="podium">基座 / 露台 / 外楼梯</option><option value="site.levels">地形 / 平台 / 道路连接</option><option value="park.pavilion">八角亭</option><option value="park.forest">公园 / 林地</option><option value="lighting">灯光 / 伪内饰</option></select></div><div><label for="feedbackview">观察视角</label><select id="feedbackview">{''.join(f'<option value="{k}">{esc(t)}</option>' for k,t,c in views)}</select></div></div><label for="issue">发现的问题</label><textarea id="issue" placeholder="例如：从基座近景看，前排柱太粗；希望保留退后的玻璃和横向露台。"></textarea><label for="preserve">希望保留的特征 / 修改方向</label><textarea id="preserve"></textarea><div class="toolbar"><button id="addfeedback" class="primary">加入反馈记录</button><button id="exportfeedback">导出反馈 JSON</button><span id="feedbackstatus" class="small"></span></div><div id="feedbacklist"></div></div></section></main>
<footer>HAF 0.2 · Namsan V1 / 2026-10-23<br>地形：SRTM / OpenTopoData。地图数据 © OpenStreetMap contributors，<a href="https://opendatacommons.org/licenses/odbl/1-0/">ODbL 1.0</a>。图片证据版权归原来源。所有建筑预览来自本次输出NBT的离线渲染。</footer>
<div class="modal" id="viewer" role="dialog" aria-modal="true" aria-label="大图查看器"><div class="modalbar"><b id="viewtitle"></b><button id="actual">原始尺寸 / 适应窗口</button><a id="downloadimage" download>下载此图</a><button id="closeviewer">关闭 ×</button></div><div class="modalbody" id="modalbody"><img id="viewimage" alt=""><p id="viewcaption"></p></div></div>
<script>const assets={json.dumps(assets,ensure_ascii=False)};const sourceHash={json.dumps(m['sha256'])};</script>'''
    content+='''<script>
const $=s=>document.querySelector(s);document.querySelectorAll('[data-image]').forEach(e=>e.src=assets[e.dataset.image].src);
let hero='overview';function setHero(k){hero=k;$('#hero').src=assets[k].src;$('#day').classList.toggle('active',k==='overview');$('#night').classList.toggle('active',k==='night');}
function show(k){const v=assets[k];$('#viewimage').src=v.src;$('#viewimage').alt=v.title;$('#viewtitle').textContent=v.title;$('#viewcaption').textContent=v.caption;$('#downloadimage').href=v.src;$('#downloadimage').download='Namsan_V1_'+k+'.png';$('#modalbody').classList.remove('actual');$('#viewer').classList.add('open');document.body.style.overflow='hidden';}
function close(){ $('#viewer').classList.remove('open');document.body.style.overflow='';}
setHero('overview');$('#day').onclick=()=>setHero('overview');$('#night').onclick=()=>setHero('night');$('#herozoom').onclick=()=>show(hero);$('#hero').onclick=()=>show(hero);document.querySelectorAll('[data-view]').forEach(e=>e.onclick=()=>show(e.dataset.view));$('#actual').onclick=()=>$('#modalbody').classList.toggle('actual');$('#closeviewer').onclick=close;document.addEventListener('keydown',e=>{if(e.key==='Escape')close();});
let notes=[];try{notes=JSON.parse(localStorage.getItem('haf_namsan_v1_feedback')||'[]');if(!Array.isArray(notes))notes=[];}catch(e){}
function list(){const el=$('#feedbacklist');el.replaceChildren();notes.forEach((n,i)=>{const p=document.createElement('p');p.className='small';p.textContent=(i+1)+'. '+n.component+' / '+n.view+' — '+n.issue;el.appendChild(p);});$('#feedbackstatus').textContent='已记录 '+notes.length+' 条';}
$('#addfeedback').onclick=()=>{const issue=$('#issue').value.trim();if(!issue){$('#feedbackstatus').textContent='请先写下具体问题';return;}notes.push({component:$('#component').value,view:$('#feedbackview').value,issue,preserve:$('#preserve').value.trim(),created_at:new Date().toISOString()});try{localStorage.setItem('haf_namsan_v1_feedback',JSON.stringify(notes));}catch(e){}$('#issue').value='';$('#preserve').value='';list();};
$('#exportfeedback').onclick=()=>{const obj={schema:'haf-feedback/1',case:'namsan_tower',baseline:'V1_r02',source_nbt_sha256:sourceHash,notes};const u=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='Namsan_V1_Feedback.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};list();
</script></body></html>'''
    path=OUT/'Namsan_Tower_HAF_V1_Review.html';path.write_text(content,encoding='utf8')
    shutil.copy2(PICS/'overview.png',OUT/'Namsan_Tower_HAF_V1_Overview.png')
    shutil.copy2(PICS/'site_top.png',OUT/'Namsan_Tower_HAF_V1_Top.png')
    shutil.copy2(RUN/'import_pack/Namsan_Tower_HAF_V1.schem',OUT/'Namsan_Tower_HAF_V1.schem')
    print(path, path.stat().st_size)

